        //
        // for (k = i+1; k < j; k++)
        //   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
        //
        // We treat this as a reduction in k over the scalar cell(v).
        // RDom over k in [i+1, j-1]  => min = i+1, extent = j - i - 1.
        Expr extent = j - i - 1;  // >= 0 because j >= i+1 in the DP.
        RDom r(i + 1, extent, "r");

        // Pure definition initializes the output for v == 0.
        cell(v) = best;

        // Reduction update: take the maximum over k.
        cell(v) = max(cell(v),
                      table_param(r.x, i) +
                          table_param(j, r.x + 1));

