        // (e.g. split/unroll r.x) to trade code size for ILP, but we
        // leave it to Halide's default schedule for simplicity and
        // portability. The main performance gain for this benchmark
        // comes from reusing the output buffer and avoiding repeated
        // allocations, rather than micro-scheduling this small
        // one-dimensional reduction.
    }

    // JIT-compile the per-cell pipeline once, ahead of timing.
    Target target = get_jit_target_from_environment();
    cell.compile_jit(target);

    // Preallocate a 1-element buffer for the cell output and reuse it
    // for every DP cell. This avoids allocating a new scalar buffer
    // on each call to cell(), which would otherwise dominate runtime
    // at large N.
    Halide::Buffer<num_t> cell_buf(1);

    // Time the DP kernel (the i/j loops plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Original kernel:
    //
    // for (i = N-1; i >= 0; i--) {
    //   for (j = i+1; j < N; j++) {
    //     ... updates to table[i][j] ...
