        // if (i+1 < N) table[i][j] = max(table[i][j], table[i+1][j]);
        // For any (i,j) with j - i = d >= 1 and j <= N-1, we have
        // i <= N-2, so i+1 < N always holds.
        best = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        // if (j-1 >= 0 && i+1 < N) {
        //   if (i < j-1)
        //     table[i][j] = max(table[i][j],
        //                        table[i+1][j-1] + match(seq[i], seq[j]));
        //   else
        //     table[i][j] = max(table[i][j], table[i+1][j-1]);
        // }
        //
        // As above, the outer bounds check is always true along the
        // active DP region, so only (i < j-1) remains.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
        Expr match_one = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1; otherwise, don't add match().
        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_one),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
        //
        // For a given diagonal offset d = j - i, the range of k is
        // independent of i: k runs from i+1 to i+d-1 inclusive,
        // which is (d-1) distinct k values.
        //
        // We express this as a reduction over r in [0, d-1), with:
        //   k = i + 1 + r
        Expr split_extent = max(d - 1, 0);   // d >= 1; for d==1, extent = 0
        RDom r(0, split_extent, "r");
        Expr k = i + r + 1;

        diag(ii) = best;
        diag(ii) = max(diag(ii),
                       table_param(k, i) + table_param(j, k + 1));
    }

