    //
    // - compute_root(): compute the whole diagonal in one shot.
    // - parallel(ii): parallelize across i along the diagonal (safe
    //   since cells on a fixed diagonal are independent).
    // - vectorize(ii): exploit SIMD across i in each parallel task.
    {
        Target t = get_jit_target_from_environment();
        const int vec = natural_vector_size<num_t>(t);

        diag.compute_root()
            .parallel(ii);
        if (vec > 1) {
            diag.vectorize(ii, vec);
        }
    }

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit();

    // Time the DP kernel (the diagonal loops plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Original kernel, conceptually:
    //
    // for (i = N-1; i >= 0; i--) {
    //   for (j = i+1; j < N; j++) {
