        const int len = n - d;   // number of (i,j) pairs with j - i == d

        // diag is a 1D Func over i in [0, len).
        Halide::Buffer<num_t> diag_vals(len);
        diag.realize(diag_vals);

        // Scatter the diagonal results back into the DP table.
        for (int i = 0; i < len; ++i) {
            int j = i + d;
            // C: table[i][j]  -> Halide: table(j, i)
            table(j, i) = diag_vals(i);
