    //  - parallelize across tiles,
    //  - vectorize within the tile.
    init_seq.compute_root();
    {
        Var io("io"), ii("ii");
        const int tile_size = 256;
        const int vec_size  = 32;  // reasonable SIMD width on modern x86
        init_seq.split(i, io, ii, tile_size)
                .parallel(io)
                .vectorize(ii, vec_size);
    }

