int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide.
    // We will treat 'table_param' as read-only inside Halide and
    // write updated values back on the host.
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    seq_param.set(seq);
    table_param.set(table);

    // Scalar parameter for the current anti-diagonal length d = j - i.
    // We will compute all cells on a given anti-diagonal in one Halide
    // call, which:
    //
    //   - Greatly amortizes JIT and call overhead compared to
    //     computing a single cell per Halide call.
    //   - Exposes a 1D parallel/vectorizable dimension (the position
    //     along the diagonal) with good data locality.
    //
    // Note: cells within the same anti-diagonal do not depend on each
    // other; every dependency goes to strictly smaller (j - i), so
    // this reordering is mathematically equivalent to the original
    // i/j nested loops.
    Param<int> d_param("d_param");

    // Func computing one entire anti-diagonal of the DP table.
    //
    // For a fixed d = j - i, indices along the diagonal are:
    //   i = t, j = t + d,  for t in [0, n-d-1].
    //
    // We define diag(t) = table[i][j] for that (i,j).
    Var t("t");
    Func diag("diag");

    {
        // Map 1D index t to (i, j) on the current diagonal.
        Expr i = t;
        Expr j = t + d_param;

        // -------------------------
        // Base DP terms (no splits)
        // -------------------------
        //
        // Original C kernel (with comments about bounds elided as in
        // the original Halide code):
        //
        // table[i][j] = max(table[i][j], table[i][j-1]);
        // table[i][j] = max(table[i][j], table[i+1][j]);
        //
        // Since the table is initialized to zero and each cell is
        // computed exactly once, max(table[i][j], ...) is equivalent
        // to max(0, ...). DP values are always non-negative, so
        // reading table[i][j] is unnecessary work. We can start with
        // the better of the two neighbors:
        //
        //    best = max(table[i][j-1], table[i+1][j]);
        //
        // C indexing table[i][j]   -> Halide table_param(j, i).
        Expr best = max(table_param(j - 1, i),
                        table_param(j,     i + 1));

        // -------------------------
        // Diagonal / pairing term
        // -------------------------
        //
        // if (i < j-1)
        //   best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        // else
        //   best = max(best, table[i+1][j-1]);
        //
        // The outer bound checks (j-1>=0, i+1<n) are always true for
        // the (i,j) we visit on valid diagonals.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));

        // match(seq[i], seq[j]) = ((seq[i] + seq[j]) == 3 ? 1 : 0)
        Expr can_pair_bases = (b1 + b2 == 3);
        Expr match_score    = cast<num_t>(can_pair_bases);

        Expr diag_base      = table_param(j - 1, i + 1);
        Expr can_form_pair  = i < (j - 1);

        // table[i+1][j-1] + match_score when i < j-1, else table[i+1][j-1]
        Expr diag_candidate =
            select(can_form_pair,
                   diag_base + match_score,
                   diag_base);

        best = max(best, diag_candidate);

        // -------------------------
        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // -------------------------
        Expr extent = j - i - 1;  // = d - 1; may be 0 when d==1.
        RDom r(i + 1, extent, "r");

        // Pure definition: initialize diag(t) with the non-split terms.
        diag(t) = best;

        // Reduction update over k.
        //
        // C: table[i][k]      -> Halide: table_param(k,     i)
        //    table[k+1][j]    ->           table_param(j, k+1)
        diag(t) = max(diag(t),
                      table_param(r.x, i) +
                      table_param(j,   r.x + 1));
    }

    // -------------------------
    // Schedule for diag
    // -------------------------
    //
    // We want to exploit parallelism across positions along the
    // diagonal (different t) while performing the reduction in k
    // sequentially per t. This is safe because each t is independent.
    //
    // We also vectorize across t for good memory locality:
    //  - table_param(r.x, i)    walks along the (fast) x-dimension.
    //  - table_param(j, r.x+1)  walks along y, but that is inherent
    //    in the algorithm.

    Var to("to"), ti("ti");
    const int tile_size   = 64; // tile size along the diagonal (t dimension)
    const int vector_width = 8; // SIMD width; tuned for typical x86

    // Schedule the pure definition.
    diag
        .compute_root()
        .split(t, to, ti, tile_size)
        .parallel(to)
        .vectorize(ti, vector_width);

    // Schedule the reduction update in a way that mirrors the pure
    // definition: same tiling and vectorization over t.
    diag.update()
        .split(t, to, ti, tile_size)
        .parallel(to)
        .vectorize(ti, vector_width);

    // JIT-compile once.
    diag.compile_jit();

    // ----------------------------------------------------------
    // Run the dynamic program, diagonal by diagonal.
    //
    // Original C order:
    //
    //   for (i = N-1; i >= 0; i--)
    //     for (j = i+1; j < N; j++)
    //       update table[i][j];
    //
    // This traverses the DP table in a valid topological order
    // (increasing j-i), but interleaves different diagonals. The
    // value at (i,j) depends only on entries with strictly smaller
    // (j-i), so *any* order that processes diagonals in increasing
    // (j-i) and processes cells within a diagonal in any order is
    // equivalent. We exploit this and compute one whole diagonal per
    // Halide call.
    // ----------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Temporary buffer to hold one diagonal worth of DP values.
    // Its size varies with d, but the maximum length is n-1, so we
    // reuse a buffer of size n and only fill the leading n-d entries.
    Halide::Buffer<num_t> diag_buf(n);

    for (int d = 1; d < n; ++d) {
        int diag_len = n - d;  // number of (i,j) with j-i == d

        d_param.set(d);

        // Realize diag over [0 .. diag_len-1].
        //
        // We use a cropped view into diag_buf so that we avoid
        // heap allocating a new buffer every iteration.
        Halide::Buffer<num_t> diag_slice =
            diag_buf.cropped(0, 0, diag_len);

        diag.realize(diag_slice);

        // Copy the computed diagonal entries back into the DP table.
        // Recall: C's table[i][j] is stored as table(j, i) in Halide.
        for (int i = 0; i < diag_len; ++i) {
            int j = i + d;
            table(j, i) = diag_slice(i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t_count = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t_count % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t_count;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
