            .vectorize(i, 32)
            .parallel(i);

    init_table.compute_root()
              .parallel(i)
              .vectorize(j, 32);

    init_seq.realize(seq);
    init_table.realize(table);
}

int main(int argc, char *argv[]) {
    // Problem size (from nussinov.hpp / PolyBench)
    int n = N;

    // Buffers:
    // seq[i]      -> seq(i)
    // table[i][j] -> table(j, i)  (C is row-major; Halide is column-major)
    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2> table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter: current subsequence length (j - i)
    Param<int> len_param("len_param");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // ------------------------------------------------------------------
    // Optimized Halide kernel: compute all cells on a fixed diagonal
    // (fixed length L = j - i) in one call.
    //
    // Key idea:
    //   The Nussinov recurrence for F[i][j] only depends on entries
    //   F[u][v] with (v - u) < (j - i). Therefore we are free to
    //   evaluate the DP in order of increasing subsequence length
    //   L = j - i, and within each length, all (i, j = i+L) are
    //   independent and can be computed in parallel.
    //
    //   For a given length L, we build a 1-D Halide Func over i:
    //       diag(i) = table[i][i+L]
    //   using the same recurrence as the scalar version, but reading
    //   all dependencies from the already-filled parts of 'table'.
    //   We then copy the resulting diagonal back into 'table' on host.
    //
    // This drastically reduces Halide call overhead: instead of
    // one Halide call per (i,j) cell, we make one call per diagonal.
    // Within each call we can parallelize over 'i'.
    // ------------------------------------------------------------------
    Var i("i");
    Func diag("diag");

    {
        Expr len = len_param;        // current subsequence length L = j - i
        Expr ii  = i;                // row index i
        Expr jj  = ii + len;         // column index j = i + L

        // Current value table[i][j]
        // (C: table[i][j] -> Halide: table_param(j, i))
        Expr best = table_param(jj, ii);

        // table[i][j] = max(table[i][j], table[i][j-1]);
        best = max(best, table_param(jj - 1, ii));

        // table[i][j] = max(table[i][j], table[i+1][j]);
        best = max(best, table_param(jj, ii + 1));

        // Diagonal / pairing term:
        //
        // if (i < j-1)
        //   table[i][j] = max(table[i][j],
        //                      table[i+1][j-1] + match(seq[i], seq[j]));
        // else
        //   table[i][j] = max(table[i][j], table[i+1][j-1]);
        //
        // where match(a,b) = ((a + b) == 3 ? 1 : 0);
        Expr b1 = cast<int32_t>(seq_param(ii));
        Expr b2 = cast<int32_t>(seq_param(jj));
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1; otherwise, don't add match().
        Expr match_term = select(ii < jj - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        Expr diag_candidate = table_param(jj - 1, ii + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   table[i][j] = max(table[i][j],
        //                      table[i][k] + table[k+1][j]);
        //
        // When j-i == len, the range of k is [i+1, i+len-1].
        // We express k = i + r, with r in [1, len-1].
        // len is a Param<int>, so the RDom extent is dynamic but
        // independent of 'i'.
        Expr r_extent = len - 1;   // may be zero when len == 1
        RDom r(1, r_extent, "r");  // empty when extent == 0

        diag(i) = best;
        Expr k = ii + r.x;
        diag(i) = max(diag(i),
                      table_param(k,  ii) +
                      table_param(jj, k + 1));
    }

    // ------------------
    // Schedule for 'diag'
    // ------------------
    // We compute each diagonal at the root and parallelize across i
    // (different cells on the same diagonal are independent). The
    // reduction in r.x remains sequential inside each i.
    diag.compute_root();
    diag.vectorize(i, 8);
    diag.update().parallel(i);

    // JIT-compile once; subsequent realizations will re-use the
    // compiled code with different 'len_param' values.
    Target target = get_jit_target_from_environment();
    diag.compile_jit(target);

    // Temporary 1D buffer to hold a diagonal; we reuse the same
    // allocation for every length, cropping it as needed.
    Halide::Buffer<num_t> diag_storage(n);

    // Time the DP kernel (the diagonal loops plus Halide calls).
    auto start = std::chrono::high_resolution_clock::now();

    // Original scalar kernel order:
    //
    // for (i = N-1; i >= 0; i--)
    //   for (j = i+1; j < N; j++)
    //     update table[i][j]
    //
    // Each table[i][j] only depends on entries with strictly smaller
    // (j - i), so an equivalent evaluation order is:
    //
    // for (len = 1; len < N; len++)        // subsequence length
    //   for (i = 0; i + len < N; i++)      // j = i + len
    //     update table[i][j]
    //
    // We use the second form, because all (i, j = i+len) at fixed 'len'
    // are independent and thus can be computed in parallel by Halide.
    for (int len = 1; len < n; ++len) {
        len_param.set(len);

        const int diag_size = n - len;  // number of (i,j) with j-i == len

        // Create a view of 'diag_storage' with the desired extent.
        auto diag_view = diag_storage.cropped(0, 0, diag_size);

        // Compute this entire diagonal in one Halide call.
        diag.realize(diag_view);

        // Copy the diagonal values back into the DP table buffer.
        // Remember: table[i][j] -> table(j, i) in Halide layout.
        for (int i_idx = 0; i_idx < diag_size; ++i_idx) {
            int j_idx = i_idx + len;
            table(j_idx, i_idx) = diag_view(i_idx);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
